class NumArray {
    vector<int> s;   // s[i] = 前 i 个元素之和
public:
    NumArray(vector<int>& nums) {
        s.assign(nums.size() + 1, 0);
        for (int i = 0; i < (int)nums.size(); ++i) s[i+1] = s[i] + nums[i];
    }
    int sumRange(int i, int j) { return s[j+1] - s[i]; }
};

class Solution {
public:
    int pivotIndex(vector<int>& nums) {
        long long total = 0;
        for (int x : nums) total += x;
        long long left = 0;
        for (int i = 0; i < (int)nums.size(); ++i) {
            if (left * 2 == total - nums[i]) return i;
            left += nums[i];
        }
        return -1;
    }
};

class Solution {
public:
    int minSubArrayLen(int target, vector<int>& nums) {
        int n = nums.size(), ans = n + 1, l = 0;
        long long cur = 0;
        for (int r = 0; r < n; ++r) {
            cur += nums[r];
            while (cur >= target) {
                ans = min(ans, r - l + 1);
                cur -= nums[l++];
            }
        }
        return ans == n + 1 ? 0 : ans;
    }
};

class Solution {
public:
    int subarraySum(vector<int>& nums, int k) {
        unordered_map<long long, int> cnt;
        cnt[0] = 1;
        long long cur = 0, ans = 0;
        for (int x : nums) {
            cur += x;
            auto it = cnt.find(cur - k);
            if (it != cnt.end()) ans += it->second;
            ++cnt[cur];
        }
        return ans;
    }
};

class Solution {
public:
    vector<int> corpFlightBookings(vector<vector<int>>& b, int n) {
        vector<int> d(n + 2, 0);
        for (auto &x : b) {
            int l = x[0], r = x[1], v = x[2];
            d[l] += v;
            d[r+1] -= v;
        }
        vector<int> ans(n);
        int cur = 0;
        for (int i = 1; i <= n; ++i) {
            cur += d[i];
            ans[i-1] = cur;
        }
        return ans;
    }
};

class Solution {
public:
    int splitArray(vector<int>& nums, int m) {
        long long lo = 0, hi = 0;
        for (int x : nums) { lo = max(lo, (long long)x); hi += x; }
        auto ok = [&](long long cap) {
            int seg = 1; long long cur = 0;
            for (int x : nums) {
                if (cur + x > cap) { ++seg; cur = 0; }
                cur += x;
            }
            return seg <= m;
        };
        while (lo < hi) {
            long long mid = lo + (hi - lo) / 2;
            if (ok(mid)) hi = mid; else lo = mid + 1;
        }
        return (int)lo;
    }
};

